def mini(label,title,l1,l2,b1,b2):
    return f'<div class="mini"><div class="scr"><span class="lbl">{label}</span><div class="ttl">{title}</div><div class="ln">{l1}</div><div class="ln">{l2}</div><div class="btns"><span class="b1">{b1}</span><span class="b2">{b2}</span></div></div></div>'
def journey(screens, heading, intro, eyebrow='How it works', sid='journey', alt=True):
    cards=''.join(f'<div class="jstep">{mini(*s[:6])}<div class="n"><b>{i+1}</b>{s[6]}</div><p>{s[7]}</p></div>' for i,s in enumerate(screens))
    return f'<section id="{sid}"{" class=alt" if alt else ""}><div class="wrap"><p class="eyebrow">{eyebrow}</p><h2>{heading}</h2><p class="sub">{intro}</p><div class="journey">{cards}</div>{ILLUS}</div></section>'
