def evidence_block():
    st=''.join(f'<div class="story"><h3>{t}</h3><p>{d}</p></div>' for t,d in STORIES)
    cite='''<div class="cite"><p><strong style="color:#fff">Why the first minutes matter.</strong> In a 2011 Harvard Business Review audit, researchers tested 2,241 US companies by submitting a test web enquiry to each and timing the first response. <a href="https://hbr.org/2011/03/the-short-life-of-online-sales-leads" rel="noopener" target="_blank">Oldroyd, McElheran and Elkington, "The Short Life of Online Sales Leads", HBR, March 2011.</a></p><div class="stat"><b>42 h</b><span>average among companies that replied within 30 days</span></div><div class="stat"><b>37%</b><span>replied within an hour</span></div><div class="stat"><b>23%</b><span>never replied</span></div></div>'''
    shift='''<div class="shift"><div><b>From</b>a notification<br><b style="margin-top:6px">To</b>context the responder can act on</div><div><b>From</b>a shared inbox<br><b style="margin-top:6px">To</b>one named owner</div><div><b>From</b>a generic reply<br><b style="margin-top:6px">To</b>a relevant one, reviewed by a person</div><div><b>From</b>one conversation<br><b style="margin-top:6px">To</b>a record with history</div><div><b>From</b>winning the enquiry<br><b style="margin-top:6px">To</b>keeping the customer</div></div>'''
    return cite+f'<h3 style="margin:34px 0 6px;font-size:22px">Patterns from the workshop demonstrations we studied</h3><p class="sub" style="margin-bottom:18px">These are illustrated patterns from software demonstrations, not Multiple Consult case studies or measured customer outcomes. They show what changes when software fits the way a business actually works.</p><div class="evid">{st}</div>{shift}'

